async function tPreflightController(){const before=process.env.ZK682_CURRENT_STARTUP_PHASE_EXECUTE;delete process.env.ZK682_CURRENT_STARTUP_PHASE_EXECUTE;try{return await import('data:text/javascript;base64,'+Buffer.from(tPreflightExtract()).toString('base64'));}finally{if(before!==undefined)process.env.ZK682_CURRENT_STARTUP_PHASE_EXECUTE=before;}}

test('T startup phase pre-import actual hosted preflight rejects committed malicious S source before every import or hosted test',async()=>{const c=await tController(),pre=await tPreflightController();assert.equal(pre.preflight.toString(),c.preflight.toString());assert(tBlock.indexOf('Verify fixed inputs and S pins before hosted tests or imports')<tBlock.indexOf('Validate accepted S source controls before original producer'));assert.doesNotMatch(pre.preflight.toString(),/\bawait\b|\bimport\s*\(/);assert.doesNotMatch(tPreflightExtract(),/\bimport\s*\(|^export async/m);for(const path of Object.keys(c.DRIVER_S_PINS)){const f=await tFixture(c);try{const identity=pre.preflight(f.workspace,f.driverSha,f.options);assert.equal(identity.driverRows.length,4);assert.equal(identity.manifest.appSourceManifestSha256,f.manifest.appSourceManifestSha256);const file=join(f.driver,path);writeFileSync(file,readFileSync(file,'utf8')+'\nglobalThis.__zk682TUnexpectedSImport = true;\n');f.driverSha=tCommit(f.driver);f.inherited.GITHUB_SHA=f.driverSha;delete globalThis.__zk682TUnexpectedSImport;assert.throws(()=>pre.preflight(f.workspace,f.driverSha,f.options),/Source pin mismatch/);await assert.rejects(()=>c.prepare(f.workspace,f.driverSha,f.options),/Source pin mismatch/);assert.equal(globalThis.__zk682TUnexpectedSImport,undefined);assert.equal(existsSync(join(f.target,c.GENERATED)),false);}finally{delete globalThis.__zk682TUnexpectedSImport;f.cleanup();}}});

test('T startup phase immutable source scalar owners reject actual identity provenance replacements and same-inode mutation',async()=>{const c=await tController();for(const owner of ['identity','provenance'])for(const hashOnly of [false,true])for(const exit of [0,2]){const f=await tFixture(c);try{const run=tRunner(f,c,await tPhase(f),{exit,owner,hashOnly});assert.equal(await c.main(f.workspace,f.driverSha,f.inherited,{...f.options,runner:run.runner}),exit===0?1:2);assert.equal(run.calls.length,2);const root=join(f.target,'simgolf-lite',c.OUT),path=owner==='identity'?'source/identity.json':'source/generated-provenance.json';assert.equal(readFileSync(join(root,path),'utf8'),JSON.stringify({foreign:'replacement'}));const receipt=JSON.parse(readFileSync(join(root,'run/owned-command-receipt.json'),'utf8'));assert.equal(receipt.exitCode,exit);assert.equal(receipt.closureVerified,true);const captured=run.captures[0];assert.notEqual(tDigest(readFileSync(join(root,path),'utf8')),tDigest(captured[path]));}finally{f.cleanup();}}for(const hashOnly of [false,true]){const f=await tFixture(c);try{const base=tRunner(f,c,await tPhase(f)),runner=(command,args,options)=>{const result=base.runner(command,args,options);const file=join(f.target,'simgolf-lite',c.OUT,'source/generated-provenance.json');if(!hashOnly)unlinkSync(file);writeFileSync(file,'foreign after smoke');return result;};assert.equal(await c.main(f.workspace,f.driverSha,f.inherited,{...f.options,runner}),1);assert.equal(base.calls.length,1);assert.equal(existsSync(join(f.target,'simgolf-lite',c.OUT,'source/identity.json')),false);assert.equal(readFileSync(join(f.target,'simgolf-lite',c.OUT,'source/generated-provenance.json'),'utf8'),'foreign after smoke');}finally{f.cleanup();}}for(const hashOnly of [false,true]){const f=await tFixture(c);try{const context=await c.prepare(f.workspace,f.driverSha,f.options);assert.equal(c.verifyOwnedSources(context),true);assert.throws(()=>c.verifyOwnedSources(context,{identityRequired:true}),/Missing fixed identity/);const file=join(context.root,'source/identity.json');context.owners.identity=c.writeOwnedScalar(file,{fixed:'source fixture'},{selfOwner:true});assert.equal(c.verifyOwnedSources(context,{identityRequired:true}),true);for(const owner of [context.owners.identity,context.owners.provenance]){const bytes=readFileSync(owner.file);if(!hashOnly)unlinkSync(owner.file);writeFileSync(owner.file,'foreign scalar');assert.throws(()=>c.verifyScalarOwner(owner));assert.equal(readFileSync(owner.file,'utf8'),'foreign scalar');if(hashOnly)writeFileSync(owner.file,bytes);}}finally{f.cleanup();}}});

import {renameSync} from 'node:fs';
function tSmokeMutation(out,kind,name='stdout.log'){const file=join(out,name);if(kind==='missing')unlinkSync(file);else if(kind==='extra')writeFileSync(join(out,'foreign.raw'),'foreign extra');else if(kind==='symlink'){const bytes=readFileSync(file);unlinkSync(file);const foreign=out+'-foreign';writeFileSync(foreign,bytes);symlinkSync(foreign,file);}else if(kind==='inode'){const bytes=readFileSync(file);renameSync(file,file+'.owned-away');writeFileSync(file,bytes);unlinkSync(file+'.owned-away');}else if(kind==='hash'){const before=lstatSync(file);writeFileSync(file,readFileSync(file).length?'same inode changed bytes':'x');assert.equal(lstatSync(file).ino,before.ino);}else if(kind==='directory'){renameSync(out,out+'-owned-away');mkdirSync(out);for(const n of ['owned-command-receipt.json','stdout.log','stderr.log'])writeFileSync(join(out,n),readFileSync(join(out+'-owned-away',n)));}else if(kind==='ancestor'){renameSync(out,out+'-owned-away');symlinkSync(out+'-owned-away',out);}else if(kind==='oversized')writeFileSync(file,'x'.repeat(name.endsWith('.log')?262145:65537));else throw Error('Unknown smoke mutation');}

test('T startup phase exact checked smoke inventory rejects unbound foreign missing extra symlink inode and hash changes',async()=>{const c=await tController();const kinds=['missing','symlink','inode','hash','oversized'];for(const name of ['owned-command-receipt.json','stdout.log','stderr.log'])for(const kind of kinds){const f=await tFixture(c);try{const x=await c.prepare(f.workspace,f.driverSha,f.options),run=tRunner(f,c,await tPhase(f)),out=join(x.app,c.OUT+'-smoke'),env=c.childEnvironment(f.inherited,f.targetSha,f.targetSha);const smoke=c.runSmoke(x.supervisor,x.app,env,out,run.runner);assert.equal(run.calls.length,1);assert.throws(()=>c.verifyCurrent(x),/Unbound smoke output/);x.checkedSmoke=smoke;assert.equal(c.verifyCurrent(x),true);assert.deepEqual(c.verifyCheckedSmoke(x),['owned-command-receipt.json','stdout.log','stderr.log'].map(n=>'simgolf-lite/'+c.OUT+'-smoke/'+n));assert.equal(smoke.inventory.root,out);for(const row of smoke.inventory.rows){const s=lstatSync(join(out,row.path));assert.equal(row.dev,s.dev);assert.equal(row.ino,s.ino);assert.equal(row.bytes,s.size);assert.equal(row.sha256,tDigest(readFileSync(join(out,row.path))));}tSmokeMutation(out,kind,name);assert.throws(()=>c.verifyCurrent(x));assert.throws(()=>c.verifyCurrent(x,{postSettlement:true}));assert.equal(run.calls.length,1);assert.equal(existsSync(join(x.root,'source/identity.json')),false);if(kind!=='missing')assert(existsSync(join(out,name)));}finally{f.cleanup();}}for(const kind of ['extra','directory','ancestor']){const f=await tFixture(c);try{const x=await c.prepare(f.workspace,f.driverSha,f.options),run=tRunner(f,c,await tPhase(f)),out=join(x.app,c.OUT+'-smoke');x.checkedSmoke=c.runSmoke(x.supervisor,x.app,c.childEnvironment(f.inherited,f.targetSha,f.targetSha),out,run.runner);assert.equal(c.verifyCurrent(x),true);tSmokeMutation(out,kind);assert.throws(()=>c.verifyCurrent(x));assert.throws(()=>c.verifyCurrent(x,{postSettlement:true}));assert.equal(run.calls.length,1);if(kind==='extra')assert.equal(readFileSync(join(out,'foreign.raw'),'utf8'),'foreign extra');}finally{f.cleanup();}}for(const kind of ['directory','symlink']){const f=await tFixture(c);try{const out=join(f.target,'simgolf-lite',c.OUT+'-smoke');mkdirSync(dirname(out),{recursive:true});writeFileSync(join(f.target,'.git/info/exclude'),'\nsimgolf-lite/artifacts/\n');if(kind==='directory'){mkdirSync(out);writeFileSync(join(out,'stdout.log'),'foreign unbound');}else{const foreign=join(f.root,'foreign-smoke');mkdirSync(foreign);writeFileSync(join(foreign,'stdout.log'),'foreign unbound');symlinkSync(foreign,out);}assert.equal(c.git(f.target,['status','--porcelain','--untracked-files=all']),'');await assert.rejects(()=>c.prepare(f.workspace,f.driverSha,f.options),/Foreign generated\/output\/smoke path/);assert.equal(readFileSync(join(out,'stdout.log'),'utf8'),'foreign unbound');assert.equal(existsSync(join(f.target,c.GENERATED)),false);}finally{f.cleanup();}}for(const exit of [0,2])for(const [kind,name] of [['missing','owned-command-receipt.json'],['hash','stdout.log'],['inode','stderr.log'],['extra','stdout.log'],['ancestor','stdout.log']]){const f=await tFixture(c);try{const base=tRunner(f,c,await tPhase(f),{exit}),out=join(f.target,'simgolf-lite',c.OUT+'-smoke'),runner=(command,args,options)=>{const result=base.runner(command,args,options);if(base.calls.length===2){const identity=JSON.parse(readFileSync(join(f.target,'simgolf-lite',c.OUT,'source/identity.json'),'utf8'));assert.equal(identity.supervisorSmoke.inventory.root,out);assert.equal(identity.supervisorSmoke.inventory.rows.length,3);tSmokeMutation(out,kind,name);}return result;};assert.equal(await c.main(f.workspace,f.driverSha,f.inherited,{...f.options,runner}),exit===0?1:2);assert.equal(base.calls.length,2);const root=join(f.target,'simgolf-lite',c.OUT);for(const [path,bytes] of Object.entries(base.captures[0]))assert.equal(readFileSync(join(root,path),'utf8'),bytes);assert.equal(c.artifactBounds(root).rows.length,7);assert.equal(JSON.parse(readFileSync(join(root,'run/owned-command-receipt.json'),'utf8')).exitCode,exit);if(kind==='extra')assert.equal(readFileSync(join(out,'foreign.raw'),'utf8'),'foreign extra');}finally{f.cleanup();}}});
